typedef float rational_t;
typedef int control_id_t;
typedef int axis_id_t;

enum device_id_t
{
	INVALID_DEVICE_ID = -1,
	JOYSTICK1_DEVICE = 1,
	JOYSTICK2_DEVICE,
	JOYSTICK3_DEVICE,
	JOYSTICK4_DEVICE,
	ANY_LOCAL_JOYSTICK = 12
};

enum control_t
{
	CT_BOOLEAN,
	CT_RATIONAL,
};

class input_device;

class device_axis
{
public:
	device_id_t device;
	axis_id_t axis;
	int control_axis;
};

template<class T>
class list
{
public:
	class const_iterator
	{
		void *node;
	public:
		const T& operator*() const;
		const T* operator->() const;
		const_iterator& operator++();
		bool operator!=(const const_iterator&) const;
	};
	const_iterator begin() const;
	const_iterator end() const;
	unsigned int size() const;
};

typedef list<device_axis> device_axis_list_t;

class game_control
{
public:
	control_id_t name;
	control_t type;
	device_axis_list_t mapping;
};

template<class K, class V>
class map
{
public:
	struct value_type
	{
		K first;
		V second;
	};
	class const_iterator
	{
		void *node;
	public:
		const value_type& operator*() const;
		const value_type* operator->() const;
		bool operator!=(const const_iterator&) const;
	};
	const_iterator find(const K&) const;
	const_iterator end() const;
};

typedef map<control_id_t, game_control> control_map_t;

class input_mgr
{
	char singleton_layout[8];
	void *rumble_ptr;
	char device_map[12];
	control_map_t control_map;
public:
	input_device *get_device(device_id_t id) const;
	rational_t get_control_state_helper(input_device *devptr, axis_id_t axis, int control_axis, control_t ctype) const;
	rational_t get_control_state(device_id_t dev_id, control_id_t control) const;
};

#define assert(x) ((void)0)

rational_t input_mgr::get_control_state( device_id_t dev_id, control_id_t control ) const
{
	control_map_t::const_iterator it = control_map.find( control );
	assert( it != control_map.end() );
	const game_control& ctrl = (*it).second;

	// If the control is not mapped, it's pinned at 0.0f.
	if ( !ctrl.mapping.size() )
	{
		return 0.0f;
	}


	const device_axis_list_t& dalist = ctrl.mapping;
	device_axis_list_t::const_iterator dait;

	input_device * device_ptr;
	rational_t value = 0.0f;

	for ( dait = dalist.begin(); dait != dalist.end(); ++dait )
	{
		//device_id_t dev_id = ( *dait ).device;
		if(dev_id == ANY_LOCAL_JOYSTICK)
		{ // need to check against all joystick ports
			for ( int i=JOYSTICK1_DEVICE; i<=JOYSTICK4_DEVICE; i++ )
			{
				device_ptr = get_device( (device_id_t) i );
				if(device_ptr)
					value += get_control_state_helper(device_ptr,(*dait).axis,(*dait).control_axis,ctrl.type);  //measures axis
			}
		}
		else
		{ // just check against specified controller port
			device_ptr = get_device( dev_id );
			if(device_ptr)
				value += get_control_state_helper(device_ptr,(*dait).axis,(*dait).control_axis,ctrl.type);  //measures axis
		}
	}
	return value;
}
